## Checks

::: {#31ab83f9 .cell execution_count=3}
``` {.python .cell-code}
if have_data:
    errors, warnings = [], []
    src, fac = clean["sources"], clean["factors"]

    # Each table against the codebook
    for name, df in clean.items():
        file = Path(TABLES[name]["file"]).name
        for v in TABLES[name]["variables"]:
            col = df[v["name"]]
            if v.get("required"):
                empty = col == ""
                if empty.any():
                    errors.append(f"{file}: {int(empty.sum())} row(s) have an empty {v['name']} (line {lines(empty)}).")
            if v["values"]:
                bad = (col != "") & ~col.isin(v["values"])
                if bad.any():
                    found = sample(col[bad])
                    errors.append(f"{file}: {v['name']} has value(s) outside the codebook: {found} (line {lines(bad)}). Allowed: {', '.join(v['values'])}.")

    # Sources
    repeated = src["source_id"].duplicated(keep=False) & (src["source_id"] != "")
    if repeated.any():
        errors.append(f"included_sources_raw.csv: source_id values repeated: {sample(src.loc[repeated, 'source_id'])}.")
    if DEDUP.exists():
        dedup_ids = set(pd.read_csv(DEDUP, dtype=str)["record_id"])
        unknown = set(src["record_id"]) - dedup_ids - {""}
        if unknown:
            errors.append(f"included_sources_raw.csv: {len(unknown)} record_id value(s) are not in deduplicated_records.csv: {sample(unknown)}.")
    else:
        warnings.append("deduplicated_records.csv not found, so record_id values were not checked.")
    if INCLUDED.exists():
        included = set(pd.read_csv(INCLUDED, dtype=str)["source_id"])
        unknown = set(src["source_id"]) - included - {""}
        if unknown:
            errors.append(f"included_sources_raw.csv: {len(unknown)} source_id value(s) were not included in screening: {sample(unknown)}.")
        waiting = included - set(src["source_id"])
        if waiting:
            warnings.append(f"{len(waiting)} included source(s) are not charted yet: {sample(waiting)}.")
    else:
        warnings.append("included_reports.csv not found, so source_id values were not checked against screening.")

    # Factors
    unknown = set(fac["source_id"]) - set(src["source_id"]) - {""}
    if unknown:
        errors.append(f"included_factors_raw.csv: {len(unknown)} source_id value(s) are not in included_sources_raw.csv: {sample(unknown)}.")
    without = set(src["source_id"]) - set(fac["source_id"]) - {""}
    if without:
        warnings.append(f"{len(without)} charted source(s) have no factor rows: {sample(without)}.")
    same = fac.duplicated(["source_id", "factor", "factor_type", "level"], keep=False)
    if same.any():
        warnings.append(f"included_factors_raw.csv: {int(same.sum())} row(s) repeat another row (line {lines(same)}).")
    for col in ("factor_category", "level"):
        n = int((fac[col] == "").sum())
        if n:
            warnings.append(f"{n} factor row(s) have no {col} yet.")

    for w in warnings:
        print("Warning:", w)
    if errors:
        raise ValueError("Fix these problems in the charting files, then run this notebook again:\n- " + "\n- ".join(errors))
    print("No errors found.")
```
